mapper.insert:
INSERT INTO device (
    uuid, company_id, device_num, device_type_id, antenna_num, status,
    create_by, create_time, update_by, update_time, note, is_del
) VALUES (
             CAST(#{uuid} AS uuid), #{companyId}, #{deviceNum}, #{deviceTypeId}, #{antennaNum}, #{status},
             #{createBy}, #{createTime}, #{updateBy}, #{updateTime}, #{note}, #{isDel}
         )

mapper.select:
SELECT * FROM device
WHERE is_del = false

    AND device_num LIKE CONCAT('%', #{deviceNum}, '%')


    AND device_type_id = #{deviceTypeId}


    AND status = #{status}

ORDER BY create_time DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM device
WHERE is_del = false

    AND device_num LIKE CONCAT('%', #{deviceNum}, '%')


    AND device_type_id = #{deviceTypeId}


    AND status = #{status}
